actions.script:
if (!ec.user.userId) {
    ec.web.sendJsonError(401, 'Authentication required')
} else {
    const out = ec.service.sync().name('org.moqui.sso.RecentAuthServices.check#RecentAuth').disableAuthz().call() || {}
    const errors = ec.message.hasError() ? ec.message.errorsString : null
    ec.message.clearErrors()
    ec.web.sendJsonResponse({errors, recent: !!out.recent, authAgeSeconds: out.authAgeSeconds ?? null, method: out.method || null,
        secondFactor: !!out.secondFactor, authFlowId: out.authFlowId || null, authFlowList: out.authFlowList || []})
}

if (!ec.user.userId) {
    ec.web.sendJsonError(401, 'Authentication required')
} else {
    const params = ec.web.parameters
    const out = ec.service.sync().name('org.moqui.sso.RecentAuthServices.reauthenticate#User')
        .parameters({password: params.password || '', code: params.code || ''}).requireNewTransaction(true).disableAuthz().call() || {}
    const errors = ec.message.hasError() ? ec.message.errorsString : null
    ec.message.clearErrors()
    ec.web.sendJsonResponse({errors, reasonCode: errors ? 'notConfirmed' : null, reauthenticated: !!out.reauthenticated,
        codeNeeded: !!out.codeNeeded, codeText: out.codeText || null, sendableFactors: out.sendableFactors || []})
}

if (!ec.user.userId) {
    ec.web.sendJsonError(401, 'Authentication required')
} else {
    const out = ec.service.sync().name('org.moqui.sso.RecentAuthServices.send#ReauthCode')
        .parameters({factorId: ec.web.parameters.factorId || ''}).requireNewTransaction(true).disableAuthz().call() || {}
    const errors = ec.message.hasError() ? ec.message.errorsString : null
    ec.message.clearErrors()
    ec.web.sendJsonResponse({errors, sent: !!out.sent})
}
